using System.Globalization;
using SourceSharp.Abi;
using Xunit;

namespace SourceSharp.Tests;

/// <summary>
/// That <see cref="VariantParse"/> answers what the C runtime answers, over the
/// whole table, row by row.
///
/// <para>
/// <b>THE POINT IS THAT NEITHER SIDE WROTE THE TABLE.</b>
/// <c>src/sourcesharp/test/variant_convert_cases.tsv</c> is generated by
/// <c>tools/variant-oracle.c</c>, which is stock's own expressions copied out of
/// <c>variant_t::Convert</c> and <c>variant_t::ToString</c>, run against the
/// glibc the game links against. This suite recomputes every column with the
/// managed parser; <c>variant_convert_test.cpp</c> recomputes every column with
/// the real libc. Neither reads the other, and a hand-edited row fails both.
/// </para>
///
/// <para>
/// <see cref="VariantParseTests"/> is the readable half — the cases worth
/// naming, with the reason each one is ugly written beside it. This is the
/// exhaustive half, and it exists because a transcription error would otherwise
/// be invisible: I could have copied the oracle's output into an
/// <c>InlineData</c> wrongly and the test would still be green.
/// </para>
/// </summary>
public class VariantAgreementTests
{
    /// <summary>
    /// The table has to be found and it has to have rows. A suite that quietly
    /// runs zero cases is the failure mode this whole file is guarding against,
    /// so a missing file FAILS rather than skipping.
    /// </summary>
    [Fact]
    public void TheCaseTableIsFound()
        => Assert.NotNull(CaseFile.Path);

    [Fact]
    public void TheCaseTableHasStringRows()
        => Assert.True(CaseFile.Strings.Count >= 40,
                       $"only {CaseFile.Strings.Count} string rows were read from {CaseFile.Path}");

    [Fact]
    public void TheCaseTableHasFloatRows()
        => Assert.True(CaseFile.Floats.Count >= 20,
                       $"only {CaseFile.Floats.Count} float rows were read from {CaseFile.Path}");

    [Fact]
    public void AtoiAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
            Assert.Equal(row.AsInt, VariantParse.Atoi(row.Input));
    }

    [Fact]
    public void AtofAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
            Assert.Equal(row.AsFloat, CaseFile.Exact(VariantParse.Atof(row.Input)));
    }

    /// <summary>
    /// A string to a boolean goes through <c>atoi</c>, so this column is the one
    /// that disagrees with the float column on "0.5" and on "0x10".
    /// </summary>
    [Fact]
    public void StringToBooleanAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
        {
            var value = VariantValue.FromString(row.Input);
            Assert.True(value.TryConvert(VariantFieldType.Boolean, out var converted));
            Assert.Equal(row.AsBool, converted.Bool);
        }
    }

    [Fact]
    public void ScanVectorAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
        {
            var v = VariantParse.ScanVector(row.Input);

            Assert.Equal(row.VectorX, CaseFile.Exact(v.X));
            Assert.Equal(row.VectorY, CaseFile.Exact(v.Y));
            Assert.Equal(row.VectorZ, CaseFile.Exact(v.Z));
        }
    }

    [Fact]
    public void ScanColorAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
        {
            var c = VariantParse.ScanColor(row.Input);

            Assert.Equal(new Color32(row.ColorR, row.ColorG, row.ColorB, row.ColorA), c);
        }
    }

    [Fact]
    public void FormatIAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
            Assert.Equal(row.ToStringInt,
                         VariantValue.FromInt(VariantParse.Atoi(row.Input)).AsDebugText);
    }

    [Fact]
    public void FormatGAgreesWithTheRuntimeOnEveryStringRow()
    {
        foreach (var row in CaseFile.Strings)
            Assert.Equal(row.ToStringFloat,
                         VariantValue.FromFloat(VariantParse.Atof(row.Input)).AsDebugText);
    }

    /// <summary>The bracketed spelling, which is what a vector-valued input crosses as.</summary>
    [Fact]
    public void AVectorSpellsItselfAsTheRuntimeDoesOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
            Assert.Equal(row.ToStringVector,
                         VariantValue.FromVector(VariantParse.ScanVector(row.Input)).AsDebugText);
    }

    [Fact]
    public void AColourSpellsItselfAsTheRuntimeDoesOnEveryRow()
    {
        foreach (var row in CaseFile.Strings)
            Assert.Equal(row.ToStringColor,
                         VariantValue.FromColor(VariantParse.ScanColor(row.Input)).AsDebugText);
    }

    /// <summary>
    /// The float-source rows: <c>(int)</c> including the out-of-range case that
    /// is undefined in C and is <c>INT_MIN</c> on this machine, and the boolean.
    /// </summary>
    [Fact]
    public void FloatToIntegerAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Floats)
        {
            var value = VariantValue.FromFloat(row.Value);
            Assert.True(value.TryConvert(VariantFieldType.Integer, out var converted));
            Assert.Equal(row.AsInt, converted.Int);
        }
    }

    [Fact]
    public void FloatToBooleanAgreesWithTheRuntimeOnEveryRow()
    {
        foreach (var row in CaseFile.Floats)
        {
            var value = VariantValue.FromFloat(row.Value);
            Assert.True(value.TryConvert(VariantFieldType.Boolean, out var converted));
            Assert.Equal(row.AsBool, converted.Bool);
        }
    }

    [Fact]
    public void FormatGAgreesWithTheRuntimeOnEveryFloatRow()
    {
        foreach (var row in CaseFile.Floats)
            Assert.Equal(row.Spelling, VariantParse.FormatG(row.Value));
    }
}

/// <summary>
/// The generated table, read once. Its parsing is deliberately dumb: anything
/// clever here would be a second place for the two suites to disagree.
/// </summary>
internal static class CaseFile
{
    internal sealed record StringRow(
        string Input, int AsInt, string AsFloat, bool AsBool,
        string VectorX, string VectorY, string VectorZ,
        int ColorR, int ColorG, int ColorB, int ColorA,
        string ToStringInt, string ToStringFloat, string ToStringVector, string ToStringColor);

    internal sealed record FloatRow(float Value, int AsInt, bool AsBool, string Spelling);

    internal static string? Path { get; }
    internal static IReadOnlyList<StringRow> Strings { get; }
    internal static IReadOnlyList<FloatRow> Floats { get; }

    static CaseFile()
    {
        Path = RepoLayout.FindSdkFile("src/sourcesharp/test/variant_convert_cases.tsv");

        var strings = new List<StringRow>();
        var floats = new List<FloatRow>();

        if (Path is not null)
        {
            foreach (string raw in File.ReadAllLines(Path))
            {
                if (raw.Length == 0 || raw[0] == '#')
                    continue;

                string[] f = raw.Split('\t');

                if (f[0] == "S" && f.Length >= 16)
                {
                    strings.Add(new StringRow(
                        Unquote(f[1]), int.Parse(f[2], Culture), f[3], f[4] == "1",
                        f[5], f[6], f[7],
                        int.Parse(f[8], Culture), int.Parse(f[9], Culture),
                        int.Parse(f[10], Culture), int.Parse(f[11], Culture),
                        f[12], f[13], f[14], f[15]));
                }
                else if (f[0] == "F" && f.Length >= 5)
                {
                    floats.Add(new FloatRow(
                        Number(f[1]), int.Parse(f[2], Culture), f[3] == "1", f[4]));
                }
            }
        }

        Strings = strings;
        Floats = floats;
    }

    private static CultureInfo Culture => CultureInfo.InvariantCulture;

    /// <summary>
    /// A float as the oracle writes it: <c>%.9g</c>, which round-trips a float
    /// exactly, with the three special values spelled so neither side has to
    /// guess the other's rendering of them.
    /// </summary>
    internal static string Exact(float value)
    {
        if (float.IsNaN(value))
            return "nan";
        if (float.IsPositiveInfinity(value))
            return "inf";
        if (float.IsNegativeInfinity(value))
            return "-inf";

        string s = value.ToString("G9", Culture);

        // C writes 3e+09 where "G9" writes 3E+09, and %.9g's exponent is at
        // least two digits.
        int e = s.IndexOf('E');
        if (e < 0)
            return s;

        int exponent = int.Parse(s.AsSpan(e + 1), NumberStyles.Integer, Culture);
        int magnitude = Math.Abs(exponent);

        return s[..e] + "e" + (exponent < 0 ? "-" : "+")
             + (magnitude < 10 ? "0" + magnitude.ToString(Culture) : magnitude.ToString(Culture));
    }

    private static float Number(string text) => text switch
    {
        "inf" => float.PositiveInfinity,
        "-inf" => float.NegativeInfinity,
        "nan" => float.NaN,
        _ => float.Parse(text, NumberStyles.Float, Culture),
    };

    private static string Unquote(string field)
    {
        var text = new System.Text.StringBuilder();

        for (int i = 1; i + 1 < field.Length; i++)
        {
            if (field[i] != '\\')
            {
                text.Append(field[i]);
                continue;
            }

            i++;
            if (i + 1 > field.Length)
                break;

            text.Append(field[i] switch { 't' => '\t', 'n' => '\n', var c => c });
        }

        return text.ToString();
    }
}
